/**
 * "Add to calendar" and the synced calendar feed — generated by the code from
 * `events` (content contract §5). Times are Jerusalem wall-clock.
 */
import type { CmsEvent } from './cms';
import { withBase } from './cms';

const compact = (local: string) => local.replace(/[-:]/g, '').slice(0, 15).padEnd(15, '0');
const esc = (s = '') => s.replace(/\\/g, '\\\\').replace(/([,;])/g, '\\$1').replace(/\r?\n/g, '\\n');
const strip = (html = '') => html.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

/** Fold lines to 75 octets as RFC 5545 asks (approximate by characters). */
const fold = (line: string) => line.match(/.{1,70}/gu)?.join('\r\n ') ?? line;

function vevent(e: CmsEvent, site: string) {
  const url = new URL(withBase(`/events/${e.slug}/`), site).href;
  return [
    'BEGIN:VEVENT',
    `UID:${e.slug}@bikes4jlm.org`,
    `DTSTAMP:${new Date().toISOString().replace(/[-:]/g, '').slice(0, 15)}Z`,
    `DTSTART;TZID=Asia/Jerusalem:${compact(e.start)}`,
    `DTEND;TZID=Asia/Jerusalem:${compact(e.end)}`,
    `SUMMARY:${esc(e.title)}`,
    e.meeting_point ? `LOCATION:${esc(e.meeting_point)}` : '',
    `DESCRIPTION:${esc([e.summary, url].filter(Boolean).join('\n'))}`,
    `URL:${url}`,
    'END:VEVENT',
  ].filter(Boolean).map(fold);
}

const VTIMEZONE = [
  'BEGIN:VTIMEZONE', 'TZID:Asia/Jerusalem',
  'BEGIN:STANDARD', 'DTSTART:19701025T020000', 'TZOFFSETFROM:+0300', 'TZOFFSETTO:+0200', 'RRULE:FREQ=YEARLY;BYMONTH=10;BYDAY=-1SU', 'END:STANDARD',
  'BEGIN:DAYLIGHT', 'DTSTART:19700327T020000', 'TZOFFSETFROM:+0200', 'TZOFFSETTO:+0300', 'RRULE:FREQ=YEARLY;BYMONTH=3;BYDAY=-1FR', 'END:DAYLIGHT',
  'END:VTIMEZONE',
];

export function toICS(events: CmsEvent[], site: string, name = 'אופניים בשביל ירושלים') {
  return [
    'BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//bikes4jlm//events//HE', 'CALSCALE:GREGORIAN', 'METHOD:PUBLISH',
    `X-WR-CALNAME:${esc(name)}`, 'X-WR-TIMEZONE:Asia/Jerusalem',
    ...VTIMEZONE,
    ...events.flatMap((e) => vevent(e, site)),
    'END:VCALENDAR',
  ].join('\r\n');
}

/** Google Calendar "add event" link. */
export function googleCalendarUrl(e: CmsEvent, site: string) {
  const p = new URLSearchParams({
    action: 'TEMPLATE',
    text: e.title,
    dates: `${compact(e.start)}/${compact(e.end)}`,
    ctz: 'Asia/Jerusalem',
    details: [e.summary, strip(e.body)].filter(Boolean).join('\n\n') + `\n\n${new URL(withBase(`/events/${e.slug}/`), site).href}`,
    location: e.meeting_point ?? '',
  });
  return `https://calendar.google.com/calendar/render?${p}`;
}

/** Path of the per-event .ics file generated at /events/<slug>.ics */
export const icsPath = (e: CmsEvent) => withBase(`/events/${e.slug}.ics`);
